-- Keep the original migrations immutable. Internal implementations are not RPCs.
-- Filename generated by Supabase CLI 2.120.0; validated locally with PGlite.
-- Supabase JWTs may otherwise outlive logout. Check the signed session claim
-- against Auth's session row for RPCs AND direct RLS table access.
create function public.goat_session_valid() returns boolean language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=auth.uid(); claims jsonb; sid uuid;
begin
 if actor is null then return false; end if;
 if to_regclass('auth.sessions') is null then
  -- Only our explicitly local PostgreSQL adapter lacks Supabase Auth tables.
  -- An unexpected hosted schema fails closed rather than accepting a JWT.
  return to_regclass('dev_auth.sessions') is not null;
 end if;
 claims:=coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb;
 begin sid:=(claims->>'session_id')::uuid;
 exception when invalid_text_representation then return false; end;
 if sid is null then return false; end if;
 return exists(select 1 from auth.sessions s join auth.users u on u.id=s.user_id
  where s.id=sid and s.user_id=actor and (s.not_after is null or s.not_after>now())
  and u.email_confirmed_at is not null and coalesce(u.is_anonymous,false)=false
  and (u.banned_until is null or u.banned_until<=now()));
end $$;
revoke all on function public.goat_session_valid() from public,anon;
grant execute on function public.goat_session_valid() to authenticated;
create or replace function public.goat_actor() returns uuid language plpgsql stable security definer set search_path='' as $$
begin
 if not public.goat_session_valid() then raise exception 'authentication_required' using errcode='28000'; end if;
 return auth.uid();
end $$;
do $$ declare t text; begin
 foreach t in array array['goat_profiles','goat_roles','goat_leagues','goat_entries','goat_rounds','goat_games','goat_submissions','goat_picks','goat_history','goat_audit','goat_prospects','goat_drafts','goat_opportunities','goat_research_jobs','goat_memberships','goat_payment_events','goat_analytics','goat_newsletter'] loop
  execute format('create policy live_session on public.%I as restrictive for all to authenticated using((select public.goat_session_valid())) with check((select public.goat_session_valid()))',t);
 end loop;
end $$;
alter function public.goat_standings(uuid) rename to goat_standings_internal;
revoke all on function public.goat_standings_internal(uuid) from public,anon,authenticated;
create function public.goat_standings(lid uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
 perform public.goat_actor();
 if not public.goat_can_view(lid) then raise exception 'league_access_denied' using errcode='42501'; end if;
 return public.goat_standings_internal(lid);
end $$;
revoke all on function public.goat_standings(uuid) from public,anon;
grant execute on function public.goat_standings(uuid) to authenticated;

-- Existing hosted Auth accounts also need a profile; metadata never grants roles.
insert into public.goat_profiles(user_id,display_name)
select id,left(coalesce(nullif(btrim(raw_user_meta_data->>'display_name'),''),'GOAT member'),80)
from auth.users on conflict(user_id) do nothing;

alter table public.goat_research_jobs drop constraint goat_research_jobs_status_check;
alter table public.goat_research_jobs add constraint goat_research_jobs_status_check
 check(status in ('pending','running','completed','failed'));
alter table public.goat_research_jobs add column claimed_by uuid references auth.users(id);
alter table public.goat_research_jobs add column lease_token uuid;
alter table public.goat_research_jobs add column lease_until timestamptz;
alter table public.goat_research_jobs add column attempts integer not null default 0;
alter table public.goat_research_jobs add column result jsonb;
alter table public.goat_research_jobs add column finished_at timestamptz;
create index goat_research_queue on public.goat_research_jobs(status,created_at);
-- Lease tokens are returned only by the claim RPC to the claiming actor.
revoke select on public.goat_research_jobs from authenticated;
grant select(id,query,status,created_by,created_at,claimed_by,lease_until,attempts,result,finished_at) on public.goat_research_jobs to authenticated;

alter function public.goat_command(jsonb) rename to goat_command_v1;
alter function public.goat_query(jsonb) rename to goat_query_v1;
revoke all on function public.goat_command_v1(jsonb),public.goat_query_v1(jsonb) from public,anon,authenticated;

create function public.goat_command(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=public.goat_actor(); op text:=p->>'op'; job public.goat_research_jobs; result jsonb; pid uuid; spec jsonb; created uuid;
begin
 if op='competition_setup' then
  if jsonb_typeof(p->'rounds') is distinct from 'array' or jsonb_array_length(p->'rounds') not between 1 and 32 or jsonb_typeof(p->'rules') is distinct from 'object' then raise exception 'invalid_competition_setup'; end if;
  result:=public.goat_command_v1(jsonb_build_object('op','league_create','name',p->>'name','sport',p->>'sport','season',p->>'season','rules',p->'rules'||'{"approved":false}'::jsonb));
  created:=(result->>'id')::uuid;
  for spec in select * from jsonb_array_elements(p->'rounds') loop
   if (spec->>'lock_at') is null or (spec->>'lock_at')::timestamptz<=now() then raise exception 'invalid_deadline'; end if;
   perform public.goat_command_v1(spec||jsonb_build_object('op','round_create','league_id',created));
  end loop;
  -- An invalid round rolls back the league, rounds, and all audit records.
  return jsonb_build_object('id',created,'status','draft');
 elsif op='profile_update' then
  if jsonb_typeof(p->'display_name') is distinct from 'string' or length(btrim(p->>'display_name')) not between 1 and 80 then raise exception 'invalid_display_name'; end if;
  update public.goat_profiles set display_name=btrim(p->>'display_name') where user_id=actor;
  insert into public.goat_audit(actor_id,action,entity_id,detail) values(actor,op,actor,jsonb_build_object('display_name',btrim(p->>'display_name')));
  return jsonb_build_object('id',actor,'status','recorded');
 elsif op in ('research_claim','research_finish') then
  if not public.goat_has_role('researcher') then raise exception 'researcher_required' using errcode='42501'; end if;
  if op='research_claim' then
   select * into job from public.goat_research_jobs
   where status='pending' or (status='running' and lease_until<=now())
   order by created_at,id for update skip locked limit 1;
   if job.id is null then return jsonb_build_object('job',null); end if;
   update public.goat_research_jobs set status='running',claimed_by=actor,lease_token=gen_random_uuid(),lease_until=now()+interval '15 minutes',attempts=attempts+1
   where id=job.id returning * into job;
   result:=jsonb_build_object('job',to_jsonb(job));
  else
   select * into job from public.goat_research_jobs where id=(p->>'job_id')::uuid for update;
   if job.id is null or job.status<>'running' or job.claimed_by is distinct from actor or job.lease_until<=now() or job.lease_token is distinct from (p->>'lease_token')::uuid then raise exception 'research_lease_denied' using errcode='42501'; end if;
   if p->>'status' not in ('completed','failed') or p->>'status' is null or jsonb_typeof(p->'result') is distinct from 'object' or coalesce(length(p->'result'->>'summary'),0)=0 then raise exception 'research_result_required'; end if;
   if p->>'status'='completed' and (jsonb_typeof(p->'result'->'sources') is distinct from 'array' or jsonb_array_length(p->'result'->'sources')=0 or exists(select 1 from jsonb_array_elements_text(p->'result'->'sources') x where x not like 'https://%')) then raise exception 'research_sources_required'; end if;
   update public.goat_research_jobs set status=p->>'status',result=p->'result',finished_at=now(),lease_token=null,lease_until=null where id=job.id;
   result:=jsonb_build_object('id',job.id,'status',p->>'status');
  end if;
  -- Do not put bearer-like lease tokens in audit history.
  insert into public.goat_audit(actor_id,action,entity_id,detail) values(actor,op,job.id,p-'lease_token');
  return result;
 end if;
 if op='research_job' and (jsonb_typeof(p->'query') is distinct from 'string' or length(btrim(p->>'query')) not between 1 and 1000) then raise exception 'invalid_research_query'; end if;
 -- Approval and suppression share a prospect lock: concurrent changes cannot
 -- approve a draft while another transaction is suppressing its prospect.
 if op in ('crm_draft','crm_interest','crm_decide') then
  if op='crm_decide' then
   if not public.goat_has_role('approver') then raise exception 'approver_required' using errcode='42501'; end if;
   select prospect_id into pid from public.goat_drafts where id=(p->>'draft_id')::uuid;
  else
   if not public.goat_has_role('researcher') then raise exception 'researcher_required' using errcode='42501'; end if;
   pid:=(p->>'prospect_id')::uuid;
  end if;
  perform 1 from public.goat_prospects where id=pid for update;
 end if;
 return public.goat_command_v1(p);
end $$;

create function public.goat_query(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=public.goat_actor(); op text:=p->>'op'; lid uuid:=(p->>'league_id')::uuid; result jsonb;
begin
 if op='dashboard' then
  return jsonb_build_object('account',public.goat_query_v1('{"op":"me"}'),
   'leagues',(select coalesce(jsonb_agg(to_jsonb(l)||jsonb_build_object('entry_status',e.status) order by l.created_at desc),'[]') from public.goat_leagues l left join public.goat_entries e on e.league_id=l.id and e.user_id=actor where l.owner_id=actor or e.user_id=actor),
   'newsletter',(select to_jsonb(n) from public.goat_newsletter n where n.user_id=actor));
 elsif op='league' then
  result:=public.goat_query_v1(p); -- Original private-league permission gate.
  return result||jsonb_build_object(
   'server_time',now(),
   'entries',(select coalesce(jsonb_agg(to_jsonb(e)||jsonb_build_object('display_name',g.display_name)),'[]') from public.goat_entries e join public.goat_profiles g on g.user_id=e.user_id where e.league_id=lid),
   'submissions',(select coalesce(jsonb_agg(to_jsonb(s)),'[]') from public.goat_submissions s join public.goat_rounds r on r.id=s.round_id where r.league_id=lid and (s.user_id=actor or r.lock_at<=now())));
 elsif op='crm_records' then
  result:=public.goat_query_v1(p); -- Staff gate before reading queue metadata.
  return result||jsonb_build_object('research_jobs',(select coalesce(jsonb_agg(to_jsonb(j)-'lease_token' order by j.created_at),'[]') from public.goat_research_jobs j));
 end if;
 return public.goat_query_v1(p);
end $$;
revoke all on function public.goat_command(jsonb),public.goat_query(jsonb) from public,anon;
grant execute on function public.goat_command(jsonb),public.goat_query(jsonb) to authenticated;
create or replace function public.goat_health() returns jsonb language sql stable set search_path='' as $$ select '{"database_ok":true,"schema_version":3}'::jsonb; $$;
